-- ===================================================================
-- Synthetic B2B Revenue Pipeline data (MySQL source of record)
-- Generated for portfolio project: star schema + Power BI/Tableau
-- ===================================================================

CREATE DATABASE IF NOT EXISTS revenue_pipeline;
USE revenue_pipeline;

DROP TABLE IF EXISTS fact_deals;
DROP TABLE IF EXISTS dim_accounts;
DROP TABLE IF EXISTS dim_reps;
DROP TABLE IF EXISTS dim_products;
DROP TABLE IF EXISTS dim_stages;

CREATE TABLE dim_accounts (
    account_id INT PRIMARY KEY,
    account_name VARCHAR(150),
    industry VARCHAR(50),
    region VARCHAR(20),
    account_tier VARCHAR(20),
    created_date DATE
);

CREATE TABLE dim_reps (
    rep_id INT PRIMARY KEY,
    rep_name VARCHAR(100),
    region VARCHAR(20),
    manager VARCHAR(100),
    hire_date DATE
);

CREATE TABLE dim_products (
    product_id INT PRIMARY KEY,
    product_name VARCHAR(100),
    category VARCHAR(50),
    list_price DECIMAL(10,2)
);

CREATE TABLE dim_stages (
    stage_id INT PRIMARY KEY,
    stage_name VARCHAR(50),
    win_probability DECIMAL(4,2)
);

CREATE TABLE fact_deals (
    deal_id INT PRIMARY KEY,
    account_id INT,
    rep_id INT,
    product_id INT,
    stage_id INT,
    deal_name VARCHAR(200),
    created_date DATE,
    closed_date DATE NULL,
    amount DECIMAL(12,2),
    status VARCHAR(20),
    source_system VARCHAR(20),
    FOREIGN KEY (account_id) REFERENCES dim_accounts(account_id),
    FOREIGN KEY (rep_id) REFERENCES dim_reps(rep_id),
    FOREIGN KEY (product_id) REFERENCES dim_products(product_id),
    FOREIGN KEY (stage_id) REFERENCES dim_stages(stage_id)
);








